function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // cell
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // autophagy waves
  ctx.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2, H/2, 20 + i * 10, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.setLineDash([10, 10]);
    ctx.beginPath();
    ctx.arc(W/2, H/2, 20 + i * 10, 0, 2 * Math.PI);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.rotate(Math.sin(t + i) * 0.1);
  }

  // mitochondria
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 30, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();

  // lysosome
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 30, 10, 0, 2 * Math.PI);
  ctx.fill();

  // cleaning
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + Math.sin(t) * 20, H/2 + 30 + Math.cos(t) * 20);
  ctx.stroke();

  ctx.restore();
}
